INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM202GZV2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The height, in meters, of a launched object is modeled by $h(t) = -3(t - 4)^2 + 19$, where $t$ is the time in seconds after launch. What is the maximum height, in meters, the object reaches?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$16$"},{"key":"C","text":"$19$"},{"key":"D","text":"$67$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function $h(t) = -3(t - 4)^2 + 19$ is in vertex form $a(t - h)^2 + k$, where the vertex is at $(4, 19)$. Since $a = -3 < 0$, the parabola opens downward and the vertex represents the maximum. The maximum height is $19$ meters, reached at $t = 4$ seconds. The distractor $4$ comes from identifying the time at the maximum rather than the height. The distractor $16$ arises from computing $4^2 = 16$ without using the full vertex form. The distractor $67$ results from treating the coefficient as $+3$ instead of $-3$ and evaluating $3(4)^2 + 19 = 48 + 19 = 67$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20BM7TI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles are supplementary. If one angle measures $137^\\circ$, what is the measure of the other angle?', NULL, $lyceon_json$[{"key":"A","text":"$43^\\circ$"},{"key":"B","text":"$53^\\circ$"},{"key":"C","text":"$47^\\circ$"},{"key":"D","text":"$137^\\circ$"}]$lyceon_json$::jsonb, 'A', NULL, E'Supplementary angles sum to $180^\\circ$. The other angle is $180^\\circ - 137^\\circ = 43^\\circ$. The value $53^\\circ$ results from a subtraction error. The value $47^\\circ$ comes from confusing supplementary ($180^\\circ$) with complementary ($90^\\circ$) and computing $90^\\circ - 43^\\circ = 47^\\circ$. Repeating $137^\\circ$ mistakes the pair for equal angles rather than supplementary ones.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20DG28U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages of $9$ members of a hiking group are: $19, 23, 23, 27, 31, 34, 34, 34, 41$. If the oldest member ($41$ years old) is replaced by a new member who is $35$ years old, which of the following statements is true?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median decrease."},{"key":"B","text":"The mean decreases and the median stays the same."},{"key":"C","text":"The mean stays the same and the median decreases."},{"key":"D","text":"The mean decreases and the mode changes."}]$lyceon_json$::jsonb, 'B', NULL, E'The original sum of ages is $266$, giving a mean of $\\frac{266}{9} \\approx 29.6$. Replacing $41$ with $35$ reduces the sum to $260$, so the new mean is $\\frac{260}{9} \\approx 28.9$; the mean decreases. The original sorted list has the 5th value (median) of $31$. The new sorted list is $19, 23, 23, 27, 31, 34, 34, 34, 35$, and the 5th value is still $31$; the median stays the same. The claim that both decrease is wrong because the median is unchanged. The claim that the mean stays the same is incorrect since the total decreased. The mode remains $34$ in both cases and does not change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22LUV23', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set contains $11$ values. After one of the values is removed, the mean of the remaining $10$ values is $37$ and the range decreases by $4$. If the original mean of all $11$ values was $39$, what was the value that was removed?', NULL, $lyceon_json$[{"key":"A","text":"$59$"},{"key":"B","text":"$55$"},{"key":"C","text":"$63$"},{"key":"D","text":"$41$"}]$lyceon_json$::jsonb, 'A', NULL, E'The original sum of all $11$ values is $11 \\times 39 = 429$. The sum of the remaining $10$ values is $10 \\times 37 = 370$. The removed value is $429 - 370 = 59$. The value $55$ results from an arithmetic slip such as computing $429 - 374$. The value $63$ comes from an equation setup error such as computing $11 \\times 39 - 10 \\times 37$ incorrectly or adding the range change to the answer. The value $41$ results from confusing the removed value with one close to the mean rather than computing it from the sums.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22LV3KI', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A repair service charges a flat fee of $\\$74$ plus $\\$37$ per hour of labor. If the total charge for a repair was $\\$259$, how many hours of labor were billed?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set up the equation $37h + 74 = 259$. Subtracting $74$ from both sides gives $37h = 185$, and dividing by $37$ yields $h = 5$. The value $3$ results from swapping the fee and the rate, solving $74h + 37 = 259$, which gives $74h = 222$ and $h = 3$. The value $7$ results from dividing the total $259$ by $37$ without subtracting the flat fee first. The value $9$ comes from incorrectly solving $37h - 74 = 259$, giving $37h = 333$ and $h = 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM231431O', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'In a circle with center $O$ and radius $7$, central angle $AOB$ measures $\\frac{5\\pi}{9}$ radians. What is the area of the minor segment bounded by chord $AB$ and arc $AB$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{245\\pi}{18} - \\frac{49}{2}\\sin\\!\\left(\\frac{5\\pi}{9}\\right)$"},{"key":"B","text":"$\\frac{245\\pi}{18}$"},{"key":"C","text":"$\\frac{245\\pi}{18} + \\frac{49}{2}\\sin\\!\\left(\\frac{5\\pi}{9}\\right)$"},{"key":"D","text":"$\\frac{49}{2}\\sin\\!\\left(\\frac{5\\pi}{9}\\right)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of the sector with central angle $\\frac{5\\pi}{9}$ is $\\frac{1}{2}r^2\\theta = \\frac{1}{2}(49)\\!\\left(\\frac{5\\pi}{9}\\right) = \\frac{245\\pi}{18}$. The area of triangle $AOB$ is $\\frac{1}{2}r^2\\sin\\theta = \\frac{49}{2}\\sin\\!\\left(\\frac{5\\pi}{9}\\right)$. The segment area is the sector area minus the triangle area: $\\frac{245\\pi}{18} - \\frac{49}{2}\\sin\\!\\left(\\frac{5\\pi}{9}\\right)$. The value $\\frac{245\\pi}{18}$ alone is the sector area, not the segment, because it includes the triangular region. Adding the triangle area instead of subtracting it ($\\frac{245\\pi}{18} + \\frac{49}{2}\\sin\\!\\left(\\frac{5\\pi}{9}\\right)$) results from a sign error. The value $\\frac{49}{2}\\sin\\!\\left(\\frac{5\\pi}{9}\\right)$ is only the triangle area, not the segment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23DL5CG', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'A quadratic function $f$ has its vertex at $(3, -5)$ and passes through the point $(0, 13)$. What is the value of $f(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$11$"},{"key":"C","text":"$27$"},{"key":"D","text":"$32$"}]$lyceon_json$::jsonb, 'C', NULL, E'Using vertex form, $f(x) = a(x - 3)^2 - 5$. Substituting the point $(0, 13)$: $a(0 - 3)^2 - 5 = 13$, so $9a - 5 = 13$, giving $9a = 18$ and $a = 2$. Therefore $f(x) = 2(x - 3)^2 - 5$. Evaluating at $x = 7$: $f(7) = 2(7 - 3)^2 - 5 = 2(16) - 5 = 32 - 5 = 27$. The distractor $-5$ comes from selecting the $y$-coordinate of the vertex without further computation. The distractor $11$ results from incorrectly using $a = 1$ instead of $a = 2$, yielding $1(16) - 5 = 11$. The distractor $32$ comes from computing $2(4)^2 = 32$ but forgetting to subtract $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23T7H73', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $f$ is defined by $f(x) = 2x^2 - 3x + 7$. What is the value of $f(-2)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'Substituting $x = -2$ into $f(x) = 2x^2 - 3x + 7$: $f(-2) = 2(-2)^2 - 3(-2) + 7 = 2(4) + 6 + 7 = 8 + 6 + 7 = 21$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23W2GPK', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $9x + 13 = 67$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$6$"},{"key":"C","text":"$54$"},{"key":"D","text":"$\\frac{67}{9}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtract $13$ from both sides to get $9x = 54$, then divide both sides by $9$ to get $x = 6$. The value $-6$ results from a sign error when dividing. The value $54$ comes from subtracting $13$ but not dividing by $9$, stopping at an intermediate step. The value $\\frac{67}{9}$ comes from dividing $67$ by $9$ without first subtracting $13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24E01JS', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(2, -11)$ and $(6, 5)$. What is the $x$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19/4', ARRAY['19/4', '4.75'], E'The slope is $m = \\frac{5 - (-11)}{6 - 2} = \\frac{16}{4} = 4$. Using point-slope form with $(6, 5)$: $y - 5 = 4(x - 6)$, which simplifies to $y = 4x - 19$. Setting $y = 0$ to find the $x$-intercept: $0 = 4x - 19$, so $x = \\frac{19}{4}$. A common error is reversing the subtraction order in the slope formula, yielding $-4$ instead of $4$, which produces a different intercept. Another mistake is finding the $y$-intercept ($-19$) instead of the $x$-intercept.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24EXFGQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of $x^2 + 3x = 40$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Rearranging gives $x^2 + 3x - 40 = 0$. Factoring yields $(x + 8)(x - 5) = 0$, so $x = -8$ or $x = 5$. Since the question asks for the positive solution, the answer is $5$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM254Z4VA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A map uses a scale of $\\frac{3}{8}$ inch to represent $5$ miles. Two landmarks are $17$ miles apart in reality. What is the distance, in inches, between the two landmarks on the map? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '51/40', ARRAY['51/40', '1.275'], E'Each mile corresponds to $\\frac{3/8}{5} = \\frac{3}{40}$ inches on the map. For $17$ miles, the map distance is $17 \\times \\frac{3}{40} = \\frac{51}{40}$ inches. A common error is to invert the scale and compute $\\frac{5}{3/8} \\times 17$, which gives a value in miles per inch rather than inches per mile. Another error is computing $\\frac{3}{8} \\times 17 = \\frac{51}{8}$, which omits the factor of $5$ in the scale.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM255WBPG', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'If $7x - 19 > 23$, what is the least integer value of $x$ that satisfies the inequality?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $19$ to both sides gives $7x > 42$, and dividing both sides by $7$ gives $x > 6$. Since $x$ must be strictly greater than $6$, the least integer satisfying this is $7$. The value $6$ is the boundary but does not satisfy the strict inequality. The value $5$ results from a computational error such as dividing $42$ by $7$ incorrectly. The value $8$ overshoots by not recognizing that $7$ already satisfies the condition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM265RWC9', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{3x^3 - 13x^2 + 16x - 4}{x - 2} = ax^2 + bx + c$ for all values of $x$ where the expression is defined, what is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Performing polynomial long division of $3x^3 - 13x^2 + 16x - 4$ by $x - 2$: dividing $3x^3$ by $x$ gives $3x^2$; multiplying $3x^2(x - 2) = 3x^3 - 6x^2$ and subtracting yields $-7x^2 + 16x - 4$. Dividing $-7x^2$ by $x$ gives $-7x$; multiplying $-7x(x - 2) = -7x^2 + 14x$ and subtracting yields $2x - 4$. Dividing $2x$ by $x$ gives $2$; multiplying $2(x - 2) = 2x - 4$ and subtracting yields remainder $0$. So $a = 3$, $b = -7$, $c = 2$, and $a + b + c = 3 + (-7) + 2 = -2$. The distractor $-1$ results from an arithmetic slip in the subtraction steps. The distractor $2$ comes from finding only $c$ rather than the full sum $a + b + c$. The distractor $5$ comes from computing $a + c = 3 + 2 = 5$ while omitting $b$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM286XMW8', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3(2x^2 - 7x) + 4x$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^2 - 17x$"},{"key":"B","text":"$6x^2 - 21x$"},{"key":"C","text":"$6x^2 - 3x$"},{"key":"D","text":"$6x^2 + 17x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the $3$ gives $6x^2 - 21x$, and combining with $4x$ yields $6x^2 - 21x + 4x = 6x^2 - 17x$. The distractor $6x^2 - 21x$ results from distributing correctly but neglecting to combine the $+4x$ term. The distractor $6x^2 - 3x$ comes from an arithmetic slip when combining $-21x + 4x$. The distractor $6x^2 + 17x$ results from dropping the negative sign on $17x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28LDT1X', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $34$ centimeters. What is the circumference of the circle, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$17\\pi$"},{"key":"B","text":"$34\\pi$"},{"key":"C","text":"$289\\pi$"},{"key":"D","text":"$1{,}156\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d = 34\\pi$. The value $17\\pi$ uses the radius ($17$) in the formula $C = \\pi r$ instead of the correct $C = 2\\pi r = \\pi d$. The value $289\\pi$ computes $\\pi r^2 = \\pi(17)^2$, which is the area formula, not the circumference. The value $1{,}156\\pi$ computes $\\pi d^2 = \\pi(34)^2$, conflating circumference with an area-like calculation using diameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A8NOO8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What is the sum of the $y$-coordinates of the solutions to the system of equations below?$$y = x^2 - 5x + 1$$$$y = x - 4$$', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$2$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the two expressions for $y$ equal: $x^2 - 5x + 1 = x - 4$, which simplifies to $x^2 - 6x + 5 = 0$. Factoring gives $(x - 1)(x - 5) = 0$, so $x = 1$ or $x = 5$. Substituting into $y = x - 4$: when $x = 1$, $y = -3$; when $x = 5$, $y = 1$. The sum of the $y$-coordinates is $-3 + 1 = -2$. The distractor $-6$ results from incorrectly summing the $y$-values as $-3 + (-3)$. The distractor $2$ comes from a sign error when adding $-3$ and $1$. The distractor $6$ results from finding the sum of the $x$-coordinates rather than the $y$-coordinates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AANH63', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $DEF$, angle $F = 90^\\circ$, $DE = 29$, and $DF = 20$. What is the value of $\\sin(D)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21/29', ARRAY['21/29', '0.724', '.724'], E'In right triangle $DEF$ with the right angle at $F$, side $DE$ is the hypotenuse (opposite the right angle). Leg $DF = 20$ is adjacent to angle $D$, and leg $EF$ is opposite angle $D$. By the Pythagorean theorem, $EF = \\sqrt{29^2 - 20^2} = \\sqrt{841 - 400} = \\sqrt{441} = 21$. Therefore $\\sin(D) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{EF}{DE} = \\frac{21}{29}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BJ65K7', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A water tank initially contains $137$ liters. Water drains from the tank at a constant rate, and after $11$ minutes the tank contains $71$ liters. Which function $w(t)$ models the amount of water, in liters, remaining in the tank after $t$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$w(t) = 137 - 6t$"},{"key":"B","text":"$w(t) = 137 + 6t$"},{"key":"C","text":"$w(t) = 71 - 6t$"},{"key":"D","text":"$w(t) = 137 - 11t$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate of change is $\\frac{71 - 137}{11} = \\frac{-66}{11} = -6$ liters per minute. The initial amount is $137$ liters, so $w(t) = 137 - 6t$. The function $w(t) = 137 + 6t$ uses the wrong sign for the rate, implying the tank is filling rather than draining. The function $w(t) = 71 - 6t$ incorrectly uses the final amount ($71$ liters) as the initial value instead of $137$. The function $w(t) = 137 - 11t$ confuses the elapsed time ($11$ minutes) with the drainage rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C0T9KR', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9x^4 - 25y^6}{3x^2 + 5y^3}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^2 + 5y^3$"},{"key":"B","text":"$3x^2 - 5y^3$"},{"key":"C","text":"$9x^4 - 5y^3$"},{"key":"D","text":"$3x^2 - 25y^6$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $9x^4 - 25y^6$ is a difference of squares: $(3x^2)^2 - (5y^3)^2 = (3x^2 + 5y^3)(3x^2 - 5y^3)$. Dividing by $3x^2 + 5y^3$ cancels one factor, leaving $3x^2 - 5y^3$. The distractor $3x^2 + 5y^3$ results from incorrectly canceling the subtraction factor instead of the addition factor. The distractor $9x^4 - 5y^3$ arises from failing to recognize the difference-of-squares pattern and only dividing the second term. The distractor $3x^2 - 25y^6$ comes from dividing only the $9x^4$ term by $3x^2$ while leaving $25y^6$ unchanged.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C2CM5B', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'If $4(3x - 5) - 7(x + 2) = 3(x - 8) + 19$, what is the value of $5x + 3$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '75.5', ARRAY['151/2', '75.5'], E'Distribute on the left side: $12x - 20 - 7x - 14 = 5x - 34$. Distribute on the right side: $3x - 24 + 19 = 3x - 5$. The equation becomes $5x - 34 = 3x - 5$. Subtracting $3x$ from both sides gives $2x - 34 = -5$. Adding $34$ to both sides gives $2x = 29$, so $x = \\frac{29}{2}$. Substituting into $5x + 3$: $5 \\cdot \\frac{29}{2} + 3 = \\frac{145}{2} + \\frac{6}{2} = \\frac{151}{2} = 75.5$. A common error is to stop after finding $x = \\frac{29}{2}$ and report that as the answer instead of evaluating $5x + 3$. Another error is making a distribution mistake with the negative sign in $-7(x + 2)$, which yields an incorrect value of $x$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E28BBD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, angle $P$ measures $41^\\circ$ and angle $Q$ measures $67^\\circ$. An exterior angle is drawn at vertex $R$. What is the measure of this exterior angle?', NULL, $lyceon_json$[{"key":"A","text":"$72^\\circ$"},{"key":"B","text":"$108^\\circ$"},{"key":"C","text":"$113^\\circ$"},{"key":"D","text":"$139^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The interior angle at $R$ is $180^\\circ - 41^\\circ - 67^\\circ = 72^\\circ$. The exterior angle at a vertex equals the sum of the two non-adjacent interior angles: $41^\\circ + 67^\\circ = 108^\\circ$. The value $72^\\circ$ is the interior angle at $R$, not the exterior angle. The value $113^\\circ$ results from an addition error ($41 + 67 \\neq 113$). The value $139^\\circ$ comes from subtracting only one angle from $180^\\circ$ ($180 - 41 = 139$).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ECTIMF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a set of data is given by $y = 1.4x + 23$, where $x$ represents the number of practice sessions and $y$ represents the predicted score on a skills assessment. A student who attended $15$ practice sessions scored $47$ on the assessment. What is the residual for this student?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$44$"},{"key":"D","text":"$50$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted score is $y = 1.4(15) + 23 = 21 + 23 = 44$. The residual is the actual value minus the predicted value: $47 - 44 = 3$. The value $-3$ results from computing the residual as predicted minus actual, reversing the sign. The value $44$ is the predicted score itself, not the residual. The value $50$ results from incorrectly computing the predicted value, such as $1.4(15) + 23 + 6$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F1WYC3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of $40$ students, $23$ passed the midterm and $29$ passed the final exam. If $17$ students passed both exams, what is the probability that a randomly selected student who passed the midterm also passed the final exam?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{17}{40}$"},{"key":"B","text":"$\\frac{17}{29}$"},{"key":"C","text":"$\\frac{17}{23}$"},{"key":"D","text":"$\\frac{29}{40}$"}]$lyceon_json$::jsonb, 'C', NULL, E'This is a conditional probability question. Given that the student passed the midterm, the sample space is the $23$ students who passed the midterm. Of those, $17$ also passed the final. So the conditional probability is $\\frac{17}{23}$. The choice $\\frac{17}{40}$ incorrectly uses the entire class as the denominator instead of conditioning on midterm passers. The choice $\\frac{17}{29}$ conditions on final exam passers instead of midterm passers, reversing the given condition. The choice $\\frac{29}{40}$ gives the unconditional probability of passing the final, ignoring the condition entirely.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FOBR22', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$$\\begin{cases} x + y = 17 \\\\ x - y = 3 \\end{cases}$$ What is the value of $x$ in the system of equations above?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$10$"},{"key":"C","text":"$14$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations eliminates $y$: $(x + y) + (x - y) = 17 + 3$, so $2x = 20$, giving $x = 10$. The value $7$ is the value of $y$, found from $17 - 10 = 7$, and results from solving for the wrong variable. The value $14$ comes from computing $17 - 3 = 14$ without completing the required division by $2$. The value $20$ results from forgetting to divide $2x = 20$ by $2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I4RANA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $320$ voters in a county and finds that $54\\%$ support a proposed park expansion, with a margin of error of $4$ percentage points. Another researcher surveys a random sample of $80$ voters from the same county and finds that $51\\%$ support the expansion, with a margin of error of $8$ percentage points. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The first survey's result is more reliable because its margin of error is smaller."},{"key":"B","text":"The second survey's result is more accurate because the percentage is closer to $50\\%$."},{"key":"C","text":"Both surveys prove that more than half of the county's voters support the expansion."},{"key":"D","text":"Neither survey provides useful information because they report different percentages."}]$lyceon_json$::jsonb, 'A', NULL, E'A smaller margin of error indicates a more precise estimate of the population parameter, and this is achieved by the first survey''s larger sample size of $320$ voters compared to $80$. The choice claiming the second survey is more accurate because its percentage is closer to $50\\%$ confuses proximity to $50\\%$ with statistical accuracy. The choice stating both surveys prove majority support is incorrect because the second survey''s confidence interval ($51\\% \\pm 8\\%$, or $43\\%$ to $59\\%$) includes values below $50\\%$. The choice dismissing both surveys ignores that each provides a valid estimate with a stated margin of error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J0ONWB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A fitness company randomly assigns $90$ volunteers to one of three groups: Group 1 follows a new exercise program, Group 2 follows a traditional exercise program, and Group 3 does no structured exercise. After $12$ weeks, Group 1 shows the greatest average decrease in body fat percentage. Which of the following conclusions is best supported by this study design?', NULL, $lyceon_json$[{"key":"A","text":"The new exercise program causes a greater decrease in body fat percentage than the other conditions for the volunteers in this study."},{"key":"B","text":"The new exercise program will reduce body fat percentage for all adults."},{"key":"C","text":"There is an association, but not necessarily a causal relationship, between the new exercise program and decreased body fat."},{"key":"D","text":"The study cannot support any conclusion because only $90$ volunteers were used."}]$lyceon_json$::jsonb, 'A', NULL, E'Because participants were randomly assigned to the three groups, this is a randomized experiment, which can support a causal conclusion — the new exercise program caused a greater decrease in body fat for the volunteers studied. The choice claiming the program works for all adults overgeneralizes beyond the study''s volunteer sample, which may not represent all adults. The choice stating only an association exists fails to recognize that random assignment allows causal inference. The choice dismissing the study because of its sample size is incorrect; random assignment, not sample size alone, determines whether causal conclusions are valid.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J3FOMB', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'In the system of equations below, $k$ is a constant. If the system has no solution, what is the value of $k$? $$\\begin{cases} 9x - 6y = 21 \\\\ kx - 4y = 7 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$4$"},{"key":"C","text":"$6$"},{"key":"D","text":"$\\frac{9}{2}$"}]$lyceon_json$::jsonb, 'C', NULL, E'For the system to have no solution, the two lines must be parallel but not coincident. This requires equal slopes but different intercepts. Rewriting the first equation in slope-intercept form: $9x - 6y = 21$ becomes $y = \\frac{3}{2}x - \\frac{7}{2}$, so the slope is $\\frac{3}{2}$. The second equation gives $y = \\frac{k}{4}x - \\frac{7}{4}$, so the slope is $\\frac{k}{4}$. Setting slopes equal: $\\frac{k}{4} = \\frac{3}{2}$, so $k = 6$. Checking proportionality: with $k = 6$, dividing the first equation by $3$ gives $3x - 2y = 7$, while dividing the second by $2$ gives $3x - 2y = 3.5$. Since $7 \\neq 3.5$, the lines are parallel and the system has no solution. The value $-6$ introduces an incorrect sign. The value $4$ confuses the $y$-coefficient for $k$. The value $\\frac{9}{2}$ arises from an incorrect ratio of the coefficients.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JE67FM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $150$ households in a city found that the mean monthly electricity bill was $\\$137$, with a margin of error of $\\$9$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"All households in the city pay between $\\$128$ and $\\$146$ per month for electricity."},{"key":"B","text":"It is plausible that the mean monthly electricity bill for all households in the city is between $\\$128$ and $\\$146$."},{"key":"C","text":"The monthly electricity bill for a randomly selected household is exactly $\\$137$."},{"key":"D","text":"The sample was too small to draw any conclusions about the city's mean electricity bill."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error creates a confidence interval for the population mean, so it is plausible that the true mean monthly electricity bill is between $\\$137 - \\$9 = \\$128$ and $\\$137 + \\$9 = \\$146$. The choice stating all households pay within this range confuses the population mean with individual values. The choice claiming the bill is exactly $\\$137$ ignores the uncertainty represented by the margin of error. The choice claiming the sample is too small contradicts the fact that a margin of error was successfully calculated from the sample.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L9JMWW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ students found that $74$ play soccer, $58$ play basketball, and $19$ play both sports. If a student from this survey is chosen at random, what is the probability that the student plays soccer or basketball?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{113}{200}$"},{"key":"B","text":"$\\frac{132}{200}$"},{"key":"C","text":"$\\frac{74}{200}$"},{"key":"D","text":"$\\frac{19}{200}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the inclusion-exclusion principle, $P(\\text{soccer or basketball}) = \\frac{74 + 58 - 19}{200} = \\frac{113}{200}$. The choice $\\frac{132}{200}$ results from adding the two groups without subtracting those who play both, which double-counts students. The choice $\\frac{74}{200}$ counts only soccer players and ignores basketball entirely. The choice $\\frac{19}{200}$ gives the probability of playing both sports rather than either sport.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LUMRHS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right circular cone has base radius $5$ cm and height $12$ cm. The cone is cut by a plane parallel to the base at a height of $8$ cm from the base, creating a smaller similar cone on top. What is the volume of the frustum (the portion between the base and the cut), in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2{,}600\\pi}{27}$"},{"key":"B","text":"$\\frac{2{,}900\\pi}{27}$"},{"key":"C","text":"$100\\pi$"},{"key":"D","text":"$\\frac{100\\pi}{27}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The full cone has volume $V = \\frac{1}{3}\\pi(5)^2(12) = 100\\pi$ cubic cm. The cut at height $8$ from the base leaves a small cone on top with height $12 - 8 = 4$ cm. By similarity, the small cone''s radius is $5 \\times \\frac{4}{12} = \\frac{5}{3}$ cm. The small cone''s volume is $\\frac{1}{3}\\pi\\left(\\frac{5}{3}\\right)^2(4) = \\frac{1}{3}\\pi \\cdot \\frac{25}{9} \\cdot 4 = \\frac{100\\pi}{27}$. The frustum volume is $100\\pi - \\frac{100\\pi}{27} = \\frac{2700\\pi - 100\\pi}{27} = \\frac{2{,}600\\pi}{27}$. The value $\\frac{2{,}900\\pi}{27}$ results from an arithmetic error in the subtraction. The value $100\\pi$ is the full cone volume, not the frustum. The value $\\frac{100\\pi}{27}$ is the volume of the removed small cone, not the frustum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M1YXKC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular garden has a length of $13$ meters and a width of $9$ meters. What is the area of the garden, in square meters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '117', ARRAY['117'], E'The area of a rectangle is length times width: $13 \\times 9 = 117$ square meters.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MJJX9D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A student scored $73$, $88$, $91$, $85$, and $78$ on five quizzes. What is the median of these scores?', NULL, $lyceon_json$[{"key":"A","text":"$83$"},{"key":"B","text":"$85$"},{"key":"C","text":"$88$"},{"key":"D","text":"$78$"}]$lyceon_json$::jsonb, 'B', NULL, E'Arranging the scores in order gives $73, 78, 85, 88, 91$. With five values, the median is the third value: $85$. The value $83$ is the mean ($\\frac{415}{5} = 83$), which reflects confusing mean and median. The value $88$ results from selecting the fourth value rather than the third from the ordered list. The value $78$ results from choosing the second value in the ordered list.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N0I6E9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A school nutritionist observes that students who eat breakfast in the cafeteria have higher test scores than students who skip breakfast. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast in the cafeteria causes higher test scores."},{"key":"B","text":"There is an association between eating breakfast in the cafeteria and higher test scores."},{"key":"C","text":"Students who skip breakfast should be required to eat in the cafeteria to raise their scores."},{"key":"D","text":"The nutritionist's observation has no value because it was not a randomized experiment."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this is an observational study — students were not randomly assigned to eat or skip breakfast — the nutritionist can conclude only that an association exists between eating breakfast and higher test scores. The choice claiming causation is not supported because confounding variables (such as household income or sleep habits) could explain the relationship. The choice recommending a policy change assumes a causal relationship that the study design cannot establish. The choice dismissing the observation entirely is too strong; observational studies provide valid evidence of association even though they cannot establish causation.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O45P4V', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A shipping company charges a flat fee of $\\$13$ plus $\\$4$ per pound for express delivery. A customer has a budget of at most $\\$61$ for shipping. Which inequality represents all possible weights $w$, in pounds, the customer can ship?', NULL, $lyceon_json$[{"key":"A","text":"$4w + 13 \\leq 61$"},{"key":"B","text":"$4w + 13 \\geq 61$"},{"key":"C","text":"$13w + 4 \\leq 61$"},{"key":"D","text":"$4w - 13 \\leq 61$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the flat fee of $\\$13$ plus $\\$4$ per pound, giving the expression $4w + 13$. Since the customer can spend at most $\\$61$, the total must be less than or equal to $61$, yielding $4w + 13 \\leq 61$. Using $\\geq$ reverses the budget constraint, implying the customer must spend at least $\\$61$. The expression $13w + 4$ swaps the per-pound rate and the flat fee. The expression $4w - 13$ incorrectly subtracts the flat fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O9ST8P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys a random sample of $600$ adults in a state and finds that $39\\%$ favor Policy X, with a margin of error of $3.1$ percentage points at a $95\\%$ confidence level. A second poll of $600$ adults finds that $44\\%$ favor Policy X, with the same margin of error. Based on these two polls, which of the following conclusions is most justified?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $39\\%$ to $44\\%$ of adults in the state favor Policy X."},{"key":"B","text":"The confidence intervals from the two polls overlap, so the results are consistent with each other."},{"key":"C","text":"Because the polls disagree, neither provides valid information about support for Policy X."},{"key":"D","text":"The second poll is more trustworthy because it reports a higher percentage."}]$lyceon_json$::jsonb, 'B', NULL, E'The first poll''s $95\\%$ confidence interval is $39\\% \\pm 3.1\\%$, or approximately $35.9\\%$ to $42.1\\%$. The second poll''s interval is $44\\% \\pm 3.1\\%$, or approximately $40.9\\%$ to $47.1\\%$. These intervals overlap in the range from about $40.9\\%$ to $42.1\\%$, meaning the results are statistically consistent — the difference could be due to sampling variability. The choice stating exactly $39\\%$ to $44\\%$ misinterprets confidence intervals as exact bounds and conflates two separate intervals into one range. The choice dismissing both polls ignores that differing point estimates are expected due to sampling variation. The choice favoring the second poll because it shows a higher percentage reflects no statistical principle — a higher reported value does not indicate greater trustworthiness.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OA9XW8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A machine produces $134$ widgets in $4$ hours. At this rate, how many minutes does it take the machine to produce $67$ widgets?', NULL, $lyceon_json$[{"key":"A","text":"$120$"},{"key":"B","text":"$60$"},{"key":"C","text":"$2$"},{"key":"D","text":"$240$"}]$lyceon_json$::jsonb, 'A', NULL, E'The machine produces $134$ widgets in $4$ hours, so $67$ widgets (half of $134$) takes half the time: $\\frac{4}{2} = 2$ hours. Converting to minutes gives $2 \\times 60 = 120$ minutes. The value $60$ comes from correctly finding $2$ hours but reporting $1$ hour in minutes. The value $2$ results from finding $2$ hours but not converting to minutes as requested. The value $240$ results from using the full $4$ hours converted to minutes, ignoring that only half the output is needed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P1188P', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, the two legs measure $9$ and $40$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$41$"},{"key":"B","text":"$49$"},{"key":"C","text":"$31$"},{"key":"D","text":"$1{,}681$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the Pythagorean theorem, the hypotenuse is $\\sqrt{9^2 + 40^2} = \\sqrt{81 + 1600} = \\sqrt{1681} = 41$. The value $49$ results from simply adding the two legs ($9 + 40$) instead of using the Pythagorean theorem. The value $31$ comes from subtracting ($40 - 9$). The value $1{,}681$ gives $9^2 + 40^2$ without taking the square root.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P7V2E0', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $g$ satisfies $g(3) = 17$ and $g(10) = -18$. What is the value of $g(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '32', ARRAY['32'], E'The slope of $g$ is $\\frac{-18 - 17}{10 - 3} = \\frac{-35}{7} = -5$. Using the point $(3, 17)$ in point-slope form: $g(x) = -5(x - 3) + 17 = -5x + 15 + 17 = -5x + 32$. Therefore $g(0) = -5(0) + 32 = 32$. A common error is reversing the subtraction in the slope formula to get $5$ instead of $-5$, which produces $g(x) = 5x + 2$ and incorrectly gives $g(0) = 2$. Another mistake is computing the slope correctly but making an arithmetic error when combining $15 + 17$, leading to an incorrect $y$-intercept.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PLT008', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands at point $A$ on level ground and measures the angle of elevation to the top of a building as $53^\\circ$. She walks $37$ meters directly toward the building to point $C$ and measures the new angle of elevation as $71^\\circ$. Which of the following expressions gives the height of the building, in meters?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{37\\sin(53^\\circ)\\sin(71^\\circ)}{\\sin(18^\\circ)}$"},{"key":"B","text":"$\\frac{37\\sin(53^\\circ)}{\\sin(18^\\circ)}$"},{"key":"C","text":"$\\frac{37\\tan(53^\\circ)\\tan(71^\\circ)}{\\tan(71^\\circ) - \\tan(53^\\circ)}$"},{"key":"D","text":"$37\\tan(53^\\circ)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $h$ be the building height and $d$ be the horizontal distance from point $C$ to the base. Then $h = d\\tan(71^\\circ)$ and $h = (d + 37)\\tan(53^\\circ)$. Setting equal: $d\\tan(71^\\circ) = (d + 37)\\tan(53^\\circ)$, so $d(\\tan(71^\\circ) - \\tan(53^\\circ)) = 37\\tan(53^\\circ)$, giving $d = \\frac{37\\tan(53^\\circ)}{\\tan(71^\\circ) - \\tan(53^\\circ)}$. Then $h = d\\tan(71^\\circ) = \\frac{37\\tan(53^\\circ)\\tan(71^\\circ)}{\\tan(71^\\circ) - \\tan(53^\\circ)}$. The expression $\\frac{37\\sin(53^\\circ)\\sin(71^\\circ)}{\\sin(18^\\circ)}$ incorrectly applies the sine rule to the configuration without properly accounting for the right-angle geometry. The expression $\\frac{37\\sin(53^\\circ)}{\\sin(18^\\circ)}$ gives the line-of-sight distance from $A$ to the top, not the height. The expression $37\\tan(53^\\circ)$ assumes the surveyor at $A$ is exactly $37$ meters from the base, ignoring the second observation entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q70JQI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A researcher collects data on the age (in years) and resting heart rate (in beats per minute) of $6$ adults. The data are: $(29, 74)$, $(37, 71)$, $(43, 69)$, $(51, 66)$, $(58, 63)$, $(64, 61)$. The line of best fit for these data is approximately $y = -0.37x + 84.7$. Using this model, what is the predicted resting heart rate, in beats per minute, for an adult who is $46$ years old? Round your answer to the nearest tenth.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '67.7', ARRAY['67.7'], E'Substituting $x = 46$ into the model gives $y = -0.37(46) + 84.7 = -17.02 + 84.7 = 67.68$, which rounds to $67.7$ beats per minute. A common error is using a positive slope instead of negative, giving $0.37(46) + 84.7 = 101.72$. Another mistake is computing $-0.37 \\times 46$ incorrectly, for example as $-17.2$ or $-16.02$, leading to wrong predictions.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RRGWIB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store marks up an item by $35\\%$ over its wholesale cost. During a clearance event, the store then discounts the marked-up price by $28\\%$. If the item''s wholesale cost is $\\$80$, what is the clearance price, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '77.76', ARRAY['77.76'], E'The marked-up price is $80 \\times 1.35 = \\$108$. The clearance discount is $28\\%$ off $\\$108$, so the clearance price is $108 \\times (1 - 0.28) = 108 \\times 0.72 = \\$77.76$. A common error is applying the net change as $35\\% - 28\\% = 7\\%$ and computing $80 \\times 1.07 = \\$85.60$, which incorrectly treats successive percent changes as additive. Another mistake is applying the $28\\%$ discount to the wholesale price instead of the marked-up price, giving $80 \\times 0.72 = \\$57.60$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S1TZH3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle in the $xy$-plane has the equation $x^2 + y^2 - 10x + 14y + 49 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Complete the square for both variables. Group and complete: $x^2 - 10x = (x - 5)^2 - 25$ and $y^2 + 14y = (y + 7)^2 - 49$. Substituting into the equation: $(x - 5)^2 - 25 + (y + 7)^2 - 49 + 49 = 0$, which simplifies to $(x - 5)^2 + (y + 7)^2 = 25$. This is a circle centered at $(5, -7)$ with $r^2 = 25$, so the radius is $\\sqrt{25} = 5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S4IUDA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers wanted to study whether a new tutoring method improves math scores. They recruited $160$ students from a single high school. Students who volunteered for tutoring ($n = 67$) received the new method, while those who did not volunteer ($n = 93$) received no tutoring. After $8$ weeks, the tutored group''s average score increased by $14$ points, compared to $5$ points for the non-tutored group. A reporter wrote that the new tutoring method was proven to raise math scores by about $9$ points. Which of the following best explains why the reporter''s claim is not justified?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of $160$ is too small to detect a $9$-point difference."},{"key":"B","text":"Students were not randomly assigned to the groups, so the difference could be due to pre-existing motivation or ability rather than the tutoring method."},{"key":"C","text":"The study should have included students from multiple schools to be valid."},{"key":"D","text":"The $14$-point increase is not statistically significant because it is less than $20$ points."}]$lyceon_json$::jsonb, 'B', NULL, E'Because students self-selected into the tutoring group rather than being randomly assigned, this is an observational study. Students who volunteered may have been more motivated or academically stronger to begin with, creating a confounding variable. Without random assignment, the observed $9$-point difference cannot be attributed to the tutoring method alone. The choice about sample size is irrelevant to the core issue of confounding — a larger sample would not fix the lack of random assignment. The choice about multiple schools addresses generalizability but not the causal-inference problem within this school. The choice about the $14$-point threshold applies no valid statistical principle — significance depends on variability and sample size, not an arbitrary $20$-point cutoff.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SCURWJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town''s population was $12{,}400$ in 2020. By 2023, the population had increased to $13{,}578$. What is the approximate percent increase in population from 2020 to 2023?', NULL, $lyceon_json$[{"key":"A","text":"$8.7\\%$"},{"key":"B","text":"$9.5\\%$"},{"key":"C","text":"$11.78\\%$"},{"key":"D","text":"$86.8\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The increase is $13{,}578 - 12{,}400 = 1{,}178$. The percent increase is $\\frac{1{,}178}{12{,}400} \\times 100 \\approx 9.5\\%$. The value $8.7\\%$ comes from an arithmetic error in the division. The value $11.78\\%$ results from dividing $1{,}178$ by $10{,}000$ instead of by the original population of $12{,}400$, an equation setup error. The value $86.8\\%$ results from a fundamental ratio inversion such as $\\frac{12{,}400}{1{,}178} \\times 100 \\div 100$ or a similar miscalculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TAYR43', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $9$ orange candies, $14$ lemon candies, and $5$ grape candies. If one candy is selected at random, what is the probability that it is lemon?', NULL, $lyceon_json$[{"key":"A","text":"$\\dfrac{1}{2}$"},{"key":"B","text":"$\\dfrac{14}{19}$"},{"key":"C","text":"$\\dfrac{9}{28}$"},{"key":"D","text":"$\\dfrac{5}{28}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of candies is $9 + 14 + 5 = 28$. The probability of selecting a lemon candy is $\\dfrac{14}{28} = \\dfrac{1}{2}$. The value $\\dfrac{14}{19}$ results from omitting the grape candies from the total. The value $\\dfrac{9}{28}$ gives the probability of selecting an orange candy, not a lemon candy. The value $\\dfrac{5}{28}$ gives the probability of selecting a grape candy.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TML33S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a strong negative linear association between hours of television watched per week and test scores. Which of the following best describes this relationship?', NULL, $lyceon_json$[{"key":"A","text":"As hours of television increase, test scores tend to increase."},{"key":"B","text":"As hours of television increase, test scores tend to decrease."},{"key":"C","text":"There is no consistent pattern between hours of television and test scores."},{"key":"D","text":"Hours of television cause test scores to decrease."}]$lyceon_json$::jsonb, 'B', NULL, E'A strong negative linear association means that as one variable increases, the other tends to decrease. Therefore, as hours of television increase, test scores tend to decrease. The claim that test scores increase describes a positive association, not a negative one. The claim that there is no consistent pattern contradicts the description of a strong association. The claim that television causes test scores to decrease confuses correlation with causation; an association does not establish a causal relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V6YSRQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $7x + 3y = 41$. Line $q$ is perpendicular to line $p$ and passes through the point $(5, -2)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{29}{7}$"},{"key":"B","text":"$\\frac{29}{7}$"},{"key":"C","text":"$\\frac{1}{7}$"},{"key":"D","text":"$-\\frac{41}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewrite line $p$ in slope-intercept form: $3y = -7x + 41$, so $y = -\\frac{7}{3}x + \\frac{41}{3}$. The slope of line $p$ is $-\\frac{7}{3}$, so the perpendicular slope is $\\frac{3}{7}$. Using point-slope form with $(5, -2)$: $y + 2 = \\frac{3}{7}(x - 5)$. Simplifying: $y = \\frac{3}{7}x - \\frac{15}{7} - \\frac{14}{7} = \\frac{3}{7}x - \\frac{29}{7}$. The $y$-intercept is $-\\frac{29}{7}$. The value $\\frac{29}{7}$ results from a sign error when combining $-\\frac{15}{7}$ and $-\\frac{14}{7}$. The value $\\frac{1}{7}$ comes from using $-\\frac{3}{7}$ as the perpendicular slope instead of $\\frac{3}{7}$, which gives $y = -\\frac{3}{7}x + \\frac{15}{7} - \\frac{14}{7} = -\\frac{3}{7}x + \\frac{1}{7}$. The value $-\\frac{41}{3}$ results from incorrectly using $\\frac{7}{3}$ as the perpendicular slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W5YV8A', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In the figure, lines $m$ and $n$ are parallel, cut by a transversal. One of the angles formed where the transversal crosses line $m$ measures $(3x + 14)^\\circ$. The co-interior (same-side interior) angle formed where the transversal crosses line $n$ measures $(5x - 18)^\\circ$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$16$"},{"key":"C","text":"$11.75$"},{"key":"D","text":"$46$"}]$lyceon_json$::jsonb, 'A', NULL, E'Co-interior (same-side interior) angles formed by parallel lines and a transversal are supplementary, so $(3x + 14) + (5x - 18) = 180$. Simplifying: $8x - 4 = 180$, so $8x = 184$ and $x = 23$. The value $16$ comes from incorrectly setting the angles equal as if they were alternate interior angles: $3x + 14 = 5x - 18$ gives $2x = 32$, so $x = 16$. The value $11.75$ results from incorrectly treating the angles as complementary ($8x - 4 = 90$, $x = 11.75$). The value $46$ comes from doubling the correct answer, perhaps confusing $x$ with $2x$ in the final step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W6O055', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A bakery uses $7$ eggs for every $3$ loaves of bread. How many eggs are needed to bake $27$ loaves of bread?', NULL, $lyceon_json$[{"key":"A","text":"$54$"},{"key":"B","text":"$63$"},{"key":"C","text":"$81$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of eggs to loaves is $\\frac{7}{3}$. With $27$ loaves, the number of eggs is $\\frac{7}{3} \\times 27 = 7 \\times 9 = 63$. The value $54$ results from an arithmetic slip such as using $6$ instead of $7$. The value $81$ comes from incorrectly computing $3 \\times 27$, confusing the multiplier. The value $21$ comes from multiplying $7 \\times 3$ without scaling to $27$ loaves.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W8SY7J', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'$$\\begin{cases} 4x + 3y = 27 \\\\ 2x - 5y = -19 \\end{cases}$$ What is the value of $x + y$ for the solution $(x, y)$ to the system of equations above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Multiply the second equation by $2$ to get $4x - 10y = -38$. Subtract this from the first equation: $(4x + 3y) - (4x - 10y) = 27 - (-38)$, which simplifies to $13y = 65$, so $y = 5$. Substituting $y = 5$ into $4x + 3(5) = 27$ gives $4x + 15 = 27$, so $4x = 12$ and $x = 3$. Therefore $x + y = 3 + 5 = 8$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WC1AMY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylindrical water tank has a radius of $7$ feet and a height of $11$ feet. Which of the following is closest to the volume of the tank, in cubic feet?', NULL, $lyceon_json$[{"key":"A","text":"$539$"},{"key":"B","text":"$1{,}693$"},{"key":"C","text":"$564$"},{"key":"D","text":"$242$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(7)^2(11) = 539\\pi \\approx 1{,}693$ cubic feet. The value $539$ computes $r^2 h$ but omits the factor of $\\pi$. The value $564$ uses the cone formula $\\frac{1}{3}\\pi r^2 h = \\frac{539\\pi}{3} \\approx 564$, which applies to cones, not cylinders. The value $242$ computes $\\frac{\\pi r^2 h}{7} \\approx 242$ from an arithmetic error in squaring the radius.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X4JJC4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'What is the sum of all solutions to the equation below?$$\\frac{x + 3}{x - 2} + \\frac{x - 1}{x + 4} = \\frac{14x + 26}{x^2 + 2x - 8}$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Since $x^2 + 2x - 8 = (x - 2)(x + 4)$, multiply both sides by $(x - 2)(x + 4)$ to clear the denominators: $(x + 3)(x + 4) + (x - 1)(x - 2) = 14x + 26$. Expanding: $x^2 + 7x + 12 + x^2 - 3x + 2 = 14x + 26$, which simplifies to $2x^2 + 4x + 14 = 14x + 26$. Rearranging gives $2x^2 - 10x - 12 = 0$, or $x^2 - 5x - 6 = 0$. Factoring yields $(x - 6)(x + 1) = 0$, so $x = 6$ or $x = -1$. Neither value is an excluded value ($x \\neq 2$ and $x \\neq -4$), so both are valid solutions. The sum of all solutions is $6 + (-1) = 5$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X4MUD3', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = -4x + 23$. What is the value of $f(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$51$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$5$"},{"key":"D","text":"$-51$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 7$: $f(7) = -4(7) + 23 = -28 + 23 = -5$. The value $51$ results from ignoring the negative sign on the coefficient, computing $4(7) + 23 = 51$. The value $5$ comes from computing the correct magnitude but dropping the negative sign. The value $-51$ results from computing $-(4 \\cdot 7 + 23) = -51$, incorrectly distributing the negative sign to both terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YSZC3K', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'Let $a$ be a positive integer. The inequality $-3(2a - 5) + 11 \\geq 4a - 2(a + 7)$ is satisfied for all positive integers $a$ up to and including some maximum value. What is that maximum value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Expanding the left side: $-3(2a - 5) + 11 = -6a + 15 + 11 = -6a + 26$. Expanding the right side: $4a - 2(a + 7) = 4a - 2a - 14 = 2a - 14$. The inequality becomes $-6a + 26 \\geq 2a - 14$. Adding $6a$ to both sides gives $26 \\geq 8a - 14$. Adding $14$ to both sides gives $40 \\geq 8a$, so $a \\leq 5$. Since $a$ must be a positive integer, the maximum value is $5$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZJYQAG', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $5x - 9y = 63$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -7)$"},{"key":"B","text":"$(0, 7)$"},{"key":"C","text":"$(0, -9)$"},{"key":"D","text":"$(0, 63)$"}]$lyceon_json$::jsonb, 'A', NULL, E'To find the $y$-intercept, set $x = 0$: $5(0) - 9y = 63$, giving $-9y = 63$, so $y = -7$. The $y$-intercept is $(0, -7)$. The value $(0, 7)$ results from dropping the negative sign when dividing $63$ by $-9$. The value $(0, -9)$ confuses the coefficient of $y$ with the intercept value. The value $(0, 63)$ mistakes the constant term for the $y$-coordinate without solving the equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZZD19I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $\\$145$ is on sale for $20\\%$ off. What is the sale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$\\$116$"},{"key":"B","text":"$\\$125$"},{"key":"C","text":"$\\$29$"},{"key":"D","text":"$\\$174$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discount is $20\\%$ of $\\$145$: $0.20 \\times 145 = \\$29$. The sale price is $145 - 29 = \\$116$. The value $\\$125$ results from a computational slip such as subtracting $20$ from $145$. The value $\\$29$ is the discount amount itself, not the sale price, reflecting a misread of what the question asks. The value $\\$174$ results from adding $20\\%$ to the original price rather than subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
