INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23HOQ9G', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø have documented an unusual behavioral pattern in Arctic foxes inhabiting volcanic regions of Iceland. Unlike their counterparts in Greenland and Svalbard, these foxes routinely cache food in geothermally heated soil rather than in permafrost. The warmer ground accelerates decomposition, meaning the cached prey spoils within eleven days instead of remaining preserved for months. Despite this apparent disadvantage, the Icelandic foxes continue the practice, suggesting that the thermal properties of the soil may offer other benefits — such as thawing frozen prey before consumption — that outweigh the reduced storage time.', $lyceon_json$[{"key":"A","text":"Arctic foxes in Iceland cache food in warm soil, a practice that may provide advantages despite causing prey to spoil more quickly."},{"key":"B","text":"Geothermal activity in Iceland has fundamentally altered the diet of Arctic foxes living near volcanic sites."},{"key":"C","text":"Arctic foxes in all regions rely on food caching as their primary survival strategy during winter months."},{"key":"D","text":"Researchers have concluded that Icelandic Arctic foxes are less successful foragers than those in Greenland and Svalbard."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the finding that Icelandic Arctic foxes cache food in geothermally heated soil, which spoils prey faster but may offer compensating benefits like thawing frozen prey. The choice stating that these foxes cache food in warm soil with possible advantages despite faster spoilage accurately captures this main idea. The choice about geothermal activity fundamentally altering the foxes'' diet goes beyond what the passage states — it discusses caching behavior, not overall diet change. The choice claiming all Arctic foxes rely on food caching as a primary survival strategy overgeneralizes, since the passage only discusses caching behavior in specific populations. The choice about researchers concluding that Icelandic foxes are less successful foragers is unsupported; the passage notes a trade-off, not a judgment about foraging success.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23R1FF2', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a researcher, if included in the text, would most effectively illustrate the claim that the beetle''s camouflage is context-dependent?', E'Entomologist Priya Dasgupta has studied the jewel beetle Chrysochroa fulgidissima, whose iridescent green shell has long been considered a form of warning coloration. Dasgupta''s fieldwork in mixed-canopy forests of Shikoku, Japan, challenges this interpretation. She found that the beetle''s reflective surface blends almost perfectly with sun-dappled leaves when viewed from below — the angle at which most avian predators approach — but becomes conspicuously visible against bark or dry leaf litter. Dasgupta argues that the shell functions as camouflage specifically in the microhabitat where the beetles spend most daylight hours: the undersides of illuminated foliage.', $lyceon_json$[{"key":"A","text":"\"The iridescence matches the spectral profile of chlorophyll-reflected light at angles between 35 and 50 degrees, precisely where canopy-foraging birds would scan for prey on leaf surfaces.\""},{"key":"B","text":"\"We counted 473 individual beetles across fourteen forest plots and found no significant variation in shell coloration between populations.\""},{"key":"C","text":"\"Warning coloration typically involves high-contrast patterns, and the beetle's uniform green does not fit that model particularly well.\""},{"key":"D","text":"\"Several other iridescent insect species in the same forest use reflective surfaces to attract mates rather than to deter predators.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is that the beetle''s camouflage is context-dependent — it works specifically when viewed from certain angles in a particular microhabitat. The quotation about iridescence matching chlorophyll-reflected light at specific angles where canopy birds scan directly illustrates how the camouflage functions in one context (viewing from below illuminated foliage) but not others. The quotation about counting beetles and finding no variation in shell coloration addresses population uniformity, not the context-dependence of camouflage. The quotation about warning coloration and high-contrast patterns challenges the warning-coloration interpretation but does not illustrate context-dependent camouflage. The quotation about other iridescent species using reflective surfaces for mate attraction concerns different species with a different function entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24BJWIL', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "temper" most nearly mean?', E'In a 2023 essay on urban planning, architect Leila Okafor argued that cities should temper their enthusiasm for supertall skyscrapers. She contended that while such buildings generate prestige, they impose severe wind-tunnel effects on pedestrians and cast long shadows that deprive neighboring streets of sunlight for months at a time.', $lyceon_json$[{"key":"A","text":"moderate"},{"key":"B","text":"harden"},{"key":"C","text":"ignite"},{"key":"D","text":"advertise"}]$lyceon_json$::jsonb, 'A', NULL, E'Okafor argues that cities should restrain or moderate their enthusiasm for supertall buildings because of negative consequences like wind-tunnel effects and shadow coverage. The option "moderate" captures the sense of restraining excess enthusiasm. The option "harden" reflects a metallurgical meaning of "temper" (as in tempering steel) that does not fit the context of enthusiasm. The option "ignite" means to set ablaze or intensify, which is the opposite of the intended meaning. The option "advertise" has no semantic connection to "temper" in any context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26X5N0U', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'The fermentation of cacao beans initiates a cascade of biochemical reactions that produce the precursor compounds responsible for chocolate''s flavor. During this stage, microbial activity generates acetic acid, which penetrates the bean and triggers enzymatic browning. ________ without the subsequent drying and roasting steps — which reduce moisture and catalyze the Maillard reaction — the fermented beans would retain an overwhelmingly sour and astringent profile, yielding none of the complex, desirable notes associated with finished chocolate.', $lyceon_json$[{"key":"A","text":"However"},{"key":"B","text":"In other words"},{"key":"C","text":"Similarly"},{"key":"D","text":"Furthermore"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "However" because the passage shifts from describing what fermentation accomplishes (producing flavor precursors) to qualifying that accomplishment: fermentation alone is insufficient without drying and roasting. This is a pivotal contrast — the preceding sentences build up fermentation''s role, and the final sentence limits it. "In other words" would signal a restatement of the previous idea, but the sentence introduces a new and contrasting condition rather than restating what was already said. "Similarly" implies a parallel process, yet the sentence actually draws a contrast between fermentation''s contribution and its limitations. "Furthermore" suggests additional supporting information in the same direction, but the sentence reverses course by showing that fermentation by itself falls short.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27W26JA', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Musicologist Elaine Cho has analyzed the compositional notebooks of the nineteenth-century pianist Clara Schumann and found that Schumann frequently drafted melodic ideas in keys she rarely used in her published works. For example, her notebooks contain 37 sketches in B major and F-sharp minor — keys that appear in only two of her 66 published compositions. Cho notes that these keys demand awkward hand positions on the piano, making them technically challenging to perform, particularly in the virtuosic passages Schumann favored in her concert pieces. Cho therefore argues that the notebooks reveal a tension between Schumann''s compositional imagination and her practical concerns as a performer, suggesting that ________', $lyceon_json$[{"key":"A","text":"Schumann's published output underrepresents her full range of harmonic interest because she filtered out keys that were impractical for the performance contexts she prioritized."},{"key":"B","text":"Schumann considered her notebook sketches to be finished compositions that she chose not to publish for personal reasons unrelated to performance difficulty."},{"key":"C","text":"the keys of B major and F-sharp minor were generally avoided by all nineteenth-century pianist-composers due to the technical limitations of contemporary pianos."},{"key":"D","text":"Schumann's preference for virtuosic passages was a commercial strategy designed to appeal to audiences who valued technical display over harmonic complexity."}]$lyceon_json$::jsonb, 'A', NULL, E'Cho''s argument centers on a tension between Schumann''s compositional imagination (sketching in challenging keys) and her practical performance concerns (avoiding those keys in published works with virtuosic passages). The logical completion is that Schumann''s published works underrepresent her harmonic range because she excluded keys impractical for her performance priorities. The choice about notebook sketches being finished compositions dismissed for personal reasons contradicts Cho''s specific explanation that performance difficulty was the filtering factor. The choice about all nineteenth-century pianist-composers avoiding these keys overgeneralizes from Schumann''s individual case to an entire generation without textual support. The choice about virtuosic passages as a commercial strategy introduces an economic motivation the passage never discusses — Cho frames the issue as artistic-practical tension, not market calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2825P9Q', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the third sentence in the overall structure of the text?', E'Literary scholar Tomoko Arai has proposed that the unreliable narrator in Akutagawa Ryūnosuke''s "In a Grove" serves a different purpose than the unreliable narrators found in Western modernist fiction. Whereas writers such as Ford Madox Ford used narrative unreliability to explore individual psychology, Akutagawa, according to Arai, deployed it to expose the social mechanisms through which conflicting testimonies are institutionally managed. The overlapping, contradictory accounts in "In a Grove" thus function less as windows into disturbed minds and more as a commentary on how judicial and communal systems construct an official version of events. Arai''s reading has been contested by scholars who argue that Akutagawa''s primary concern was epistemological — questioning whether objective truth is attainable — rather than sociological.', $lyceon_json$[{"key":"A","text":"It draws out a consequence of Arai's interpretive framework by recharacterizing the role of the conflicting testimonies."},{"key":"B","text":"It provides biographical details about Akutagawa to support Arai's claim."},{"key":"C","text":"It concedes a limitation of Arai's argument before presenting counterevidence."},{"key":"D","text":"It shifts the discussion from Akutagawa's work to a broader analysis of Western modernist fiction."}]$lyceon_json$::jsonb, 'A', NULL, E'The third sentence begins with "thus," signaling that it draws a consequence from the preceding claim. It recharacterizes the contradictory accounts — not as explorations of psychology but as commentary on institutional truth-making — thereby extending and clarifying Arai''s framework. The option about biographical details is incorrect because the sentence contains no biographical information about Akutagawa. The option about conceding a limitation is wrong because the concession and counterargument appear in the fourth sentence, not the third. The option about shifting to Western modernist fiction misreads the sentence''s direction; the third sentence focuses on Akutagawa''s story, not on Western writers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28MD1KW', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Rina Okabe spent three years studying the waggle dance of Apis dorsata, the giant honeybee native to South and Southeast Asia. Unlike Apis mellifera, whose waggle dance communicates the direction and distance of a food source through movements performed on a vertical ______ Apis dorsata performs its dance on the exposed outer surface of the nest, using the sun''s position directly rather than transposing it onto a gravitational reference frame.', $lyceon_json$[{"key":"A","text":"comb; Apis"},{"key":"B","text":"comb. Apis"},{"key":"C","text":"comb, Apis"},{"key":"D","text":"comb Apis"}]$lyceon_json$::jsonb, 'C', NULL, E'The introductory phrase beginning with "Unlike Apis mellifera" is a dependent element that must be separated from the main clause by a comma. The entire construction "Unlike Apis mellifera, whose waggle dance communicates the direction and distance of a food source through movements performed on a vertical comb" modifies the subject of the main clause, "Apis dorsata." Because this introductory element is not an independent clause, placing a semicolon or period after "comb" would incorrectly treat it as a complete sentence, creating a fragment. Omitting punctuation entirely produces a run-on.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28ZJ27T', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing a report on urban beekeeping, a student wants to emphasize the economic benefit that rooftop hives can provide to city residents. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29PTD6A', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Elara Voss spent seventeen months cataloging bioluminescent organisms along the floor of the Mariana Trench. Her team identified thirty-nine previously undocumented species ______ several of which produce light in wavelengths invisible to most deep-sea predators. Voss noted that these organisms cluster near hydrothermal vents, suggesting that their bioluminescence may serve a role in chemical signaling rather than in attracting prey.', $lyceon_json$[{"key":"A","text":"species, several"},{"key":"B","text":"species; several"},{"key":"C","text":"species. Several"},{"key":"D","text":"species several"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses a comma to introduce the nonrestrictive relative clause "several of which produce light in wavelengths invisible to most deep-sea predators." Because "several of which" begins a dependent clause rather than an independent one, a semicolon or period would incorrectly treat the relative clause as a standalone sentence, creating a fragment. Omitting punctuation entirely produces a run-on construction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A5AD98', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'Neuroscientist Rina Vasquez has challenged the long-held view that adult brains are essentially fixed. Her longitudinal study of 137 taxi drivers in Bogota found that their hippocampal volume increased measurably over a four-year period, reinforcing the claim that neural architecture remains remarkably plastic well into middle age. Vasquez cautioned, however, that this adaptability is domain-specific and should not be taken as evidence that all cognitive functions are equally changeable.', $lyceon_json$[{"key":"A","text":"adaptable"},{"key":"B","text":"synthetic"},{"key":"C","text":"decorative"},{"key":"D","text":"rigid"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage discusses neural architecture that changes in response to experience, with hippocampal volume increasing over time. The sentence further glosses the idea with the word "adaptability," confirming that "plastic" here means adaptable or capable of being reshaped. The option "synthetic" refers to the material-science meaning of plastic (an artificial polymer), which is irrelevant to neural tissue. The option "decorative" confuses plastic with a visual-arts sense that does not apply to brain structure. The option "rigid" is the direct opposite of the meaning conveyed; the passage explicitly argues against the view that adult brains are fixed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DJW4TX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The hawksbill sea turtle''s shell has long been prized for its distinctive overlapping pattern of translucent plates. ________ the international trade in hawksbill shell products was banned under CITES in 1977, illegal poaching continues to threaten the species in parts of Southeast Asia and the Caribbean.', $lyceon_json$[{"key":"A","text":"Although"},{"key":"B","text":"Consequently"},{"key":"C","text":"Specifically"},{"key":"D","text":"Meanwhile"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "Although" because the sentence sets up a concession: the ban exists, yet poaching continues. This contrast between a protective measure and its limited effectiveness requires a concessive transition. "Consequently" wrongly implies that the ongoing poaching is a logical result of the ban. "Specifically" incorrectly suggests the second clause is elaborating on a detail from the first. "Meanwhile" implies two simultaneous but unrelated events, missing the concessive relationship between the ban and the continued threat.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DRIG5E', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The fruit fly Drosophila melanogaster has been a staple of genetics laboratories for over a century. Its genome was fully sequenced in the year 2000, and researchers have identified the functions of roughly 13,600 of its genes. [underline]Despite this extensive knowledge, scientists at the University of Zurich recently discovered that nearly 200 Drosophila genes had been misclassified in existing databases.[/underline] Their findings prompted a comprehensive review of annotation standards across multiple model organisms.', $lyceon_json$[{"key":"A","text":"It introduces a surprising complication that motivates the research described afterward."},{"key":"B","text":"It provides historical background on the study of Drosophila genetics."},{"key":"C","text":"It summarizes the central finding of the University of Zurich study."},{"key":"D","text":"It questions whether Drosophila is a suitable organism for genetic research."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence uses "Despite this extensive knowledge" to pivot from the established success of Drosophila research to a surprising problem — the misclassification of nearly 200 genes — which then motivates the comprehensive review described in the final sentence. It thus introduces a complication that drives the subsequent action. The option claiming it provides historical background is incorrect because the historical context appears in the preceding sentences, not the underlined one. The option stating it summarizes the central finding captures only part of the sentence''s role; the sentence''s structural function is to pivot the text toward the review, not merely to report a finding. The option suggesting it questions Drosophila''s suitability overstates the text; the passage never doubts the organism''s value, only the accuracy of specific database annotations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GXQMM6', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine ecologists studying coral reefs near Palau have hypothesized that parrotfish grazing prevents algal overgrowth on damaged coral, thereby allowing coral larvae to recolonize bare surfaces more rapidly after bleaching events. The researchers noted that reef sections with higher parrotfish densities appeared to recover from a 2019 bleaching event roughly twice as fast as sections where parrotfish were scarce.', $lyceon_json$[{"key":"A","text":"Reef sections where parrotfish were experimentally excluded showed significantly greater algal coverage and slower coral recovery than sections where parrotfish had unrestricted access."},{"key":"B","text":"Parrotfish populations near Palau have increased steadily over the past two decades due to fishing restrictions."},{"key":"C","text":"Coral bleaching events near Palau have become more frequent since 2010, affecting both shallow and deep reef zones."},{"key":"D","text":"Parrotfish in Palau consume a wider variety of algal species than parrotfish in other regions of the Pacific."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers hypothesize that parrotfish grazing prevents algal overgrowth and allows faster coral recovery. The finding that experimental exclusion of parrotfish led to more algal coverage and slower coral recovery directly tests and supports this causal claim. The finding about parrotfish population increases due to fishing restrictions provides context about population trends but does not address whether grazing causes faster recovery. The finding about increased frequency of bleaching events concerns the stressor itself, not the role of parrotfish in recovery. The finding about dietary breadth of Palau parrotfish describes their foraging range but does not connect grazing to coral recovery rates.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L2XYSE', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Peatlands cover only about 3 percent of the Earth''s land surface, yet they store approximately twice as much carbon as all the world''s forests combined. When peatlands are drained for agriculture, however, the exposed peat oxidizes and releases carbon dioxide at rates that can rival those of industrial facilities. In Indonesia alone, drained peatlands contributed an estimated 504 million metric tons of CO₂ in 2015 — roughly equivalent to the annual emissions of the entire country of Canada. Conservationists have responded by advocating for "paludiculture," a farming approach that keeps water tables high while cultivating wetland-adapted crops such as sago palm and cattail.', $lyceon_json$[{"key":"A","text":"It presents a resource's value, describes a threat to that value, quantifies the threat, and then introduces a proposed solution."},{"key":"B","text":"It contrasts two competing scientific theories about peatland management and evaluates the evidence for each."},{"key":"C","text":"It traces the historical development of peatland agriculture from ancient practices to modern innovations."},{"key":"D","text":"It argues that Indonesian peatland policy should serve as a model for other countries."}]$lyceon_json$::jsonb, 'A', NULL, E'The text follows a clear four-part structure: it establishes peatlands'' carbon-storage value, explains the threat posed by drainage, provides a specific quantitative example from Indonesia, and concludes with a proposed farming solution (paludiculture). The option about two competing theories is incorrect because the passage does not present rival scientific theories — it describes a problem and a response. The option about historical development is wrong because the passage does not trace any historical timeline of agricultural practices. The option about Indonesian policy serving as a model overstates the text; Indonesia is cited as an example of the problem''s scale, not as a policy model.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MMC14H', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing about coral reef monitoring, a marine biology student wants to highlight a technological advancement that has improved researchers'' ability to track reef health over large areas. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NWCUEK', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the 1920s, archaeologist Hilda Petersen excavated a cluster of storage pits at a Bronze Age settlement near Lake Vättern in Sweden. Each pit contained residues of barley, emmer wheat, and flax — a combination that Petersen interpreted as evidence of a mixed-crop subsistence economy. Recent lipid analysis of the pit walls, however, reveals that the residues are layered chronologically: barley at the deepest levels, emmer wheat in the middle, and flax near the surface. Moreover, radiocarbon dating shows that each layer corresponds to a distinct century of use. Taken together, these findings suggest that ________', $lyceon_json$[{"key":"A","text":"the settlement's agricultural focus shifted from one primary crop to another over successive centuries rather than relying on all three crops simultaneously."},{"key":"B","text":"Petersen's original interpretation was correct because all three crops were cultivated in the same geographic area."},{"key":"C","text":"flax was the most economically important crop at the settlement throughout the entire period of occupation."},{"key":"D","text":"the storage pits were used for ritual purposes rather than for practical food preservation."}]$lyceon_json$::jsonb, 'A', NULL, E'The new evidence shows that the crop residues are chronologically layered, with each layer corresponding to a different century. This directly implies a sequential shift in agricultural focus rather than simultaneous mixed-crop cultivation, making the choice about shifting from one primary crop to another the most logical completion. The choice affirming Petersen''s interpretation ignores the new chronological evidence; while all three crops were present in the same area, they were not used at the same time. The choice claiming flax was most important throughout the entire occupation contradicts the layering evidence, which shows flax only in the most recent layer. The choice about ritual purposes introduces an unsupported claim that goes far beyond what the layering and dating evidence implies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O35V9Y', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While drafting an article about historical textile production, a student wants to present a contrast between the environmental costs and the cultural significance of indigo dyeing in colonial South Carolina. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PK6ZB2', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the relationship between the two phenomena discussed in the text?', E'Biologist Renata Orlov has proposed that the dramatic population decline of the pallid sturgeon in the upper Missouri River is linked not only to dam construction — the factor most frequently cited — but also to a subtler hydrological change: the elimination of seasonal turbidity pulses. Before the dams were built, spring floods churned massive quantities of sediment into the water column, reducing light penetration and creating conditions that favored the sturgeon''s electroreceptive foraging strategy over the vision-dependent hunting of competing species. The dams not only blocked migration routes but also trapped sediment behind their walls, producing clearer downstream water year-round. Orlov argues that this persistent clarity shifted the competitive balance toward sighted predators, compounding the migratory barrier effect and accelerating the sturgeon''s decline beyond what dam obstruction alone would predict.', $lyceon_json$[{"key":"A","text":"Dam construction created the migratory barriers that caused the sturgeon's decline, and reduced turbidity is a secondary consequence with no independent ecological effect."},{"key":"B","text":"Reduced turbidity independently caused the sturgeon's decline, while dam construction affected only non-target species in the ecosystem."},{"key":"C","text":"Dam construction and reduced turbidity are distinct but interacting factors, with the loss of turbidity amplifying the decline caused by migratory barriers."},{"key":"D","text":"Reduced turbidity preceded dam construction and initially benefited the sturgeon before the dams introduced additional stressors."}]$lyceon_json$::jsonb, 'C', NULL, E'Orlov argues that dam construction both blocked migration routes and trapped sediment, producing clearer water that shifted competitive balance against the sturgeon. The passage explicitly states that reduced clarity compounded the migratory barrier effect and accelerated decline beyond what dam obstruction alone would predict. The choice identifying the two as distinct but interacting factors with turbidity loss amplifying the decline captures this relationship. The choice describing reduced turbidity as a secondary consequence with no independent effect contradicts the passage, which presents turbidity loss as having its own ecological impact through altered competitive dynamics. The choice claiming reduced turbidity independently caused the decline while dams affected only non-target species misreads the passage — dams directly affected the sturgeon''s migration. The choice stating that reduced turbidity preceded dam construction inverts the causal sequence described in the passage, where dams caused the turbidity reduction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PWPQMI', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After analyzing over fourteen hundred fossilized pollen grains from a peat bog in central Ireland, paleoecologist Niamh Callaghan reached a conclusion that contradicted decades of established ______ the region''s high concentrations of oak and elm pollen indicated that a dense broadleaf forest had persisted there for at least three millennia longer than prior studies had estimated.', $lyceon_json$[{"key":"A","text":"research, the"},{"key":"B","text":"research; however, the"},{"key":"C","text":"research the"},{"key":"D","text":"research: the"}]$lyceon_json$::jsonb, 'D', NULL, E'A colon is correct because the second clause specifies the content of the conclusion mentioned in the first clause. The statement about oak and elm pollen elaborates on what it means that Callaghan''s conclusion "contradicted decades of established research." A comma alone between these independent clauses creates a comma splice. Using "however" after a semicolon introduces a false logical contrast, since the pollen evidence constitutes the basis for the conclusion rather than opposing it. Omitting punctuation entirely fuses two independent clauses into a run-on.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QAP55T', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "sustained" most nearly mean?', E'Marine biologists studying the kelp forests off the coast of Tasmania documented a sustained decline in canopy coverage between 2011 and 2019. Over those eight years, warming ocean currents steadily reduced the density of giant kelp, transforming once-lush underwater forests into sparse patches of stunted growth.', $lyceon_json$[{"key":"A","text":"prolonged"},{"key":"B","text":"nourished"},{"key":"C","text":"endured"},{"key":"D","text":"acoustic"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a decline that continued "over those eight years," indicating that "sustained" means prolonged or continuous. The option "nourished" reflects a different meaning of "sustain" (to provide sustenance) that does not fit the context of a decline. The option "endured" means to suffer through something, which misapplies the subject — the decline itself is not suffering. The option "acoustic" has no connection to the meaning of "sustained" and is entirely unrelated to the passage''s context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
