INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RMTUSJ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the two chemists collaborated closely on the initial patent application, it was Dr. Elif Arslan, not Dr. Jonas Wendt, ______ identified the catalytic mechanism that made the synthesis of the compound commercially viable — a contribution that the Nobel committee would later single out in its citation.', $lyceon_json$[{"key":"A","text":"which"},{"key":"B","text":"whom"},{"key":"C","text":"who"},{"key":"D","text":"whose"}]$lyceon_json$::jsonb, 'C', NULL, E'The relative pronoun refers to "Dr. Elif Arslan" and serves as the subject of the verb "identified" in the cleft construction "it was Dr. Elif Arslan ... who identified." The subjective case "who" is required because the pronoun performs the action of identifying. The objective case "whom" would be appropriate only if the pronoun were the object of a verb or preposition, which it is not here. The pronoun "which" is reserved for non-human referents and cannot refer to a person. The possessive "whose" indicates ownership, which does not fit the sentence''s structure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RP5C9O', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if accurate, would most directly undermine Halvorsen''s explanation for the discrepancy?', E'Economist Lars Halvorsen analyzed census data from 2011 to 2021 and found that rural municipalities in northern Norway experienced a 14% decline in working-age population despite a simultaneous 9% increase in advertised job vacancies in those same areas. Halvorsen attributes the paradox to what he calls "amenity asymmetry": the idea that younger workers increasingly weight urban cultural amenities — restaurants, galleries, nightlife — more heavily than wage premiums when choosing where to live. Critics, however, argue that the outmigration is driven primarily by inadequate rural broadband infrastructure, which prevents remote work and forces digitally dependent workers to relocate regardless of their amenity preferences.', $lyceon_json$[{"key":"A","text":"Municipalities that invested heavily in cultural programming between 2015 and 2021 experienced the same rate of population decline as those that did not."},{"key":"B","text":"The majority of workers who left rural municipalities cited proximity to family members in urban centers as their primary motivation."},{"key":"C","text":"Rural municipalities that installed high-speed broadband between 2016 and 2019 experienced the same outmigration rates as municipalities without broadband upgrades."},{"key":"D","text":"Advertised job vacancies in northern Norway included a higher proportion of part-time and seasonal positions than vacancies in urban areas."}]$lyceon_json$::jsonb, 'A', NULL, E'Halvorsen''s explanation is amenity asymmetry — younger workers leave because rural areas lack urban cultural amenities. If municipalities that invested heavily in cultural programming experienced the same decline as those that did not, then improving amenities did not reduce outmigration, which directly undermines the claim that amenity deficits drive the exodus. The finding about workers citing family proximity as their motivation provides an alternative explanation but does not specifically test Halvorsen''s amenity hypothesis. The finding about broadband installation and outmigration rates would undermine the critics'' broadband-based counter-explanation rather than Halvorsen''s amenity-based explanation. The finding about part-time and seasonal vacancies addresses the quality of available jobs but does not bear on whether amenity preferences drive relocation decisions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SI8U32', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason Kamata''s findings were initially controversial?', E'In 1987, geochemist Yuko Kamata published results from her analysis of manganese nodules collected from the floor of the Mariana Trough. Her measurements indicated that certain nodules contained concentrations of rare earth elements — particularly europium and terbium — that were seventeen times higher than those reported in nodules from the central Pacific. Kamata attributed the enrichment to hydrothermal fluid circulation along the trough''s spreading ridge. Her colleagues, however, objected that existing models of hydrothermal chemistry could not account for such extreme concentrations and suggested that contamination during sample preparation was the more plausible explanation. Subsequent expeditions in 1993 and 1997 collected uncontaminated samples that confirmed Kamata''s original measurements.', $lyceon_json$[{"key":"A","text":"Kamata used analytical methods that had not been independently validated by other laboratories."},{"key":"B","text":"The concentrations Kamata reported were far higher than existing hydrothermal models predicted was possible."},{"key":"C","text":"Kamata's hypothesis about hydrothermal fluid circulation contradicted the accepted theory of plate tectonics."},{"key":"D","text":"The manganese nodules Kamata studied were collected from a region previously considered geologically inactive."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that Kamata''s colleagues objected because existing models of hydrothermal chemistry could not account for the extreme concentrations she reported. The choice about concentrations exceeding what existing models predicted directly reflects this stated reason. The choice about unvalidated analytical methods is not mentioned in the passage — the objection concerned the plausibility of the concentrations, not the methods used to measure them. The choice about contradicting plate tectonics overstates the controversy; the passage describes a disagreement about hydrothermal chemistry, not plate tectonics. The choice about a geologically inactive region is fabricated; the passage identifies the Mariana Trough''s spreading ridge as the site, which implies geological activity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SVREM1', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When archaeologist Dalia Sorokin began excavating a site near Novgorod in 2016, she expected to find remnants of a medieval trading post. Instead, her team unearthed fragments of birch-bark manuscripts that ______ to the ninth century, making them among the oldest known examples of written communication in the region.', $lyceon_json$[{"key":"A","text":"dates"},{"key":"B","text":"dated"},{"key":"C","text":"would have been dating"},{"key":"D","text":"has dated"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage is narrated consistently in the past tense ("began," "expected," "unearthed"), so the verb describing the manuscripts must also be in the past tense. The simple past "dated" maintains tense consistency and correctly agrees with the plural subject "manuscripts." The choice "dates" is singular present tense, conflicting with both the plural subject and the past-tense narrative. The choice "would have been dating" introduces an unwarranted conditional progressive construction. The choice "has dated" uses a singular present-perfect form that disagrees with the plural "manuscripts."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TRTNDW', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit of the New Zealand kauri tree takes roughly eighteen months to mature from pollination to seed release — one of the longest maturation periods of any conifer species. During this time, the developing cones are heavily targeted by the kauri snail, which consumes immature seeds before they harden. Ecologist Maren Tan observed that kauri trees at higher elevations, where kauri snails are absent due to colder temperatures, produce viable seed crops nearly every year. By contrast, lowland kauri trees in snail-dense habitats produce viable crops only once every three to four years, suggesting that ________', $lyceon_json$[{"key":"A","text":"snail predation reduces the frequency with which lowland kauri trees successfully produce mature seeds."},{"key":"B","text":"kauri trees at higher elevations have evolved a faster seed maturation process than lowland trees."},{"key":"C","text":"the kauri snail preferentially targets seeds that have already reached maturity."},{"key":"D","text":"lowland kauri trees compensate for snail predation by producing significantly larger individual seeds."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts high-elevation kauri trees (no snails, annual viable crops) with lowland trees (snails present, viable crops only every three to four years). The logical completion is that snail predation reduces the frequency of successful seed production in lowland trees, which directly follows from the stated contrast. The choice about faster seed maturation at higher elevations is unsupported — the passage attributes the difference to snail absence, not to an evolved change in maturation rate. The choice about snails targeting mature seeds contradicts the passage, which states that snails consume immature seeds before they harden. The choice about lowland trees producing larger seeds is an unsupported claim not implied by any evidence in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UX3IA1', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Among the artifacts recovered from a sixteenth-century shipwreck off the coast of Mozambique ______ a collection of porcelain bowls, each bearing a distinctive cobalt-blue glaze that ceramicists have traced to a kiln in Jingdezhen active during the early Ming dynasty.', $lyceon_json$[{"key":"A","text":"were"},{"key":"B","text":"was"},{"key":"C","text":"are"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence uses inverted syntax: the subject "a collection of porcelain bowls" follows the verb rather than preceding it. Because "a collection" is singular, the verb must be singular as well. Rearranged in standard order, the sentence reads "A collection of porcelain bowls was among the artifacts recovered from a sixteenth-century shipwreck." The plural choices "were," "are," and "have been" incorrectly agree with "bowls" or "artifacts" rather than with the true singular subject "a collection."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VH9SHB', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of fossilized trilobites discovered in a limestone quarry near Granville, Ohio, ______ scientists with evidence that the region was once submerged beneath a shallow tropical sea during the Ordovician period, roughly four hundred and fifty million years ago.', $lyceon_json$[{"key":"A","text":"have provided"},{"key":"B","text":"provide"},{"key":"C","text":"provides"},{"key":"D","text":"are providing"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "collection," which is singular, so the verb must also be singular. The phrase "of fossilized trilobites discovered in a limestone quarry near Granville, Ohio" is a prepositional phrase modifying "collection" and does not change the subject-verb agreement. The singular verb "provides" correctly agrees with the singular subject. The plural forms "have provided," "provide," and "are providing" incorrectly treat "trilobites" as the subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WUHB8O', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the Jodrell Bank Observatory have cataloged over 3,100 pulsars since the first was detected in 1967. Many of these rapidly spinning neutron stars emit radio waves in predictable intervals, earning them the nickname "cosmic lighthouses." ________ a subset of pulsars known as millisecond pulsars rotate so quickly — up to 716 times per second — that their timing stability rivals that of atomic clocks, making them candidates for deep-space navigation systems.', $lyceon_json$[{"key":"A","text":"In fact"},{"key":"B","text":"By contrast"},{"key":"C","text":"Nevertheless"},{"key":"D","text":"For instance"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "In fact" because the sentence that follows intensifies the preceding claim about predictable timing by presenting an even more extreme case — millisecond pulsars whose stability rivals atomic clocks. This is an emphatic elaboration, not a contradiction or a random example. "By contrast" incorrectly signals opposition when the passage is building on the same idea. "Nevertheless" implies the new information counters or qualifies the previous point, but the passage is amplifying it. "For instance" would frame the millisecond pulsars as merely one illustration of predictable intervals, but the sentence actually escalates the claim rather than exemplifying it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
