INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YV2BA9', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geomorphologists have long attributed the sinuous paths of meandering rivers primarily to lateral erosion on the outer bank of each bend. Recent computational models by Schwenk and Foufoula-Georgiou, though, demonstrate that the curvature of a meander migrates downstream over time in ways that lateral erosion alone cannot explain. ________ the models reveal that sediment deposition on inner banks and variations in floodplain soil cohesion interact with erosive forces to produce the distinctive scroll-bar patterns visible in satellite imagery.', $lyceon_json$[{"key":"A","text":"Regardless"},{"key":"B","text":"More precisely"},{"key":"C","text":"In addition"},{"key":"D","text":"For example"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "More precisely" because the third sentence sharpens the claim made in the second: after stating that lateral erosion alone cannot explain downstream curvature migration, the passage specifies exactly which additional mechanisms — sediment deposition and soil-cohesion variation — account for the observed patterns. The relationship is one of refinement, not mere addition. "Regardless" signals that the following point holds irrespective of what precedes it, which contradicts the tight logical connection between the two sentences. "In addition" would treat the final sentence as a separate, parallel finding, but it is actually a clarification of the same finding introduced in the preceding sentence. "For example" frames the final sentence as an illustration of a general claim, yet the sentence identifies causal mechanisms rather than providing an illustrative case.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZO5XSD', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2019 study, geochemist Priya Narayanan analyzed sediment cores extracted from Lake Hovsgol in northern Mongolia. The oldest layers of volcanic ash matched the chemical signature of an eruption site over eight hundred kilometers to the ______ the youngest layers, by contrast, originated from a previously unmapped vent less than fifty kilometers from the lake. This finding prompted Narayanan to propose that the region''s volcanic activity had shifted dramatically over the past twelve thousand years.', $lyceon_json$[{"key":"A","text":"south, the"},{"key":"B","text":"south the"},{"key":"C","text":"south; the"},{"key":"D","text":"south: the"}]$lyceon_json$::jsonb, 'C', NULL, E'A semicolon correctly joins the two independent clauses: one stating that the oldest ash layers matched a distant eruption site and the other stating that the youngest layers originated from a nearby vent. A comma alone between these clauses produces a comma splice. Omitting punctuation entirely creates a fused sentence. A colon is inappropriate here because the second clause introduces a contrast (signaled by "by contrast") rather than an explanation or elaboration of the first clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
